import React, { useEffect, useMemo, useState } from "react";
import { useAuth } from "@/_core/hooks/useAuth";
import { startLogin } from "@/const";
import { trpc } from "@/lib/trpc";
import { OFFLINE_MAP_PACKAGES, downloadOfflinePackage, getOfflinePackageDownloadUrl, getOfflinePackageInfo, hasOfflinePackage, storeOfflinePackage } from "@/lib/offlinePackages";
import { composeStructuredAddress, getDistricts, getNeighborhoods, getStreetSuggestions, ISTANBUL_PROVINCE_ID, type AddressOption } from "@/lib/addressDirectory";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { ArrowRight, Award, Bell, Bike, Calculator, CheckCircle2, Clock3, FileUp, Headphones, MapPin, MessageCircle, Package, ShieldCheck, Sparkles, Truck, WalletCards } from "lucide-react";
import { toast } from "sonner";
import { canConfirmOrder } from "@shared/routing";
